/* jacobi-2d.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "jacobi-2d.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      {
	A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
	B[i][j] = ((DATA_TYPE) i*(j+3) + 3) / n;
      }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations:
   - Use a pipelined update over the spatial dimension:
       * First compute row i of B from A.
       * As soon as B rows i-2, i-1 and i are available,
         compute row i-1 of A from B.
     This keeps recently-written B rows hot in cache when they are
     read to update A, improving data locality vs. the original
     "full B sweep then full A sweep" approach.

   - Within each row update, operate with explicit row pointers and
     simple pointer increments instead of repeated 2D indexing.
     This yields unit-stride accesses that are very friendly to the
     cache and to auto-vectorization, while preserving the exact
     numerical semantics (same boundary conditions, same stencil).
*/
static
void kernel_jacobi_2d[[gnu::flatten, gnu::noinline]](int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int t, i, j;

#pragma scop
  /* Effective loop bounds used by PolyBench. */
  const int n_inner = _PB_N;
  const int i_start = 1;
  const int i_end   = n_inner - 1; /* exclusive upper bound */
  const int j_start = 1;
  const int j_end   = n_inner - 1; /* exclusive upper bound */

  /* Stencil weight (constant factor), computed once. */
  const DATA_TYPE c = SCALAR_VAL(0.2);

  for (t = 0; t < _PB_TSTEPS; t++)
    {
      /* For very small grids (no interior points), nothing to do. */
      if (n_inner <= 2)
        continue;

      /* ---------- First B row: i = 1 ---------------------------------
         Compute B[1][j] from A using a 5-point stencil.
         This initializes the pipeline; A is still the state at time t. */
      {
        const int i_row = i_start; /* 1 */

        DATA_TYPE *Bi      = &B[i_row][j_start];
        DATA_TYPE *Ai_left = &A[i_row][j_start-1];
        DATA_TYPE *Ai      = &A[i_row][j_start];
        DATA_TYPE *Ai_right= &A[i_row][j_start+1];
        DATA_TYPE *Ai_up   = &A[i_row-1][j_start];
        DATA_TYPE *Ai_down = &A[i_row+1][j_start];

        for (j = j_start; j < j_end; ++j)
          {
            /* B[i_row][j] = 0.2 * (A[i][j] + A[i][j-1] + A[i][j+1]
                                    + A[i+1][j] + A[i-1][j]); */
            Bi[0] = c * (Ai[0] + Ai_left[0] + Ai_right[0] +
                         Ai_up[0] + Ai_down[0]);

            /* Advance to the next column (unit-stride accesses). */
            ++Bi;
            ++Ai_left;
            ++Ai;
            ++Ai_right;
            ++Ai_up;
            ++Ai_down;
          }
      }

      /* ---------- Main pipelined loop over interior rows -------------
         For i = 2 .. n_inner-2:
           1) Compute B[i][*] from A.
           2) Compute A[i-1][*] from B, now that B[i-2], B[i-1], B[i]
              are all available.

         This reorders independent computations compared to the original
         code, but preserves the dependency structure:
         - B[*] depends only on A[*] at the same time step.
         - A[*] depends only on B[*] from the same time step.
      */
      for (i = i_start + 1; i < i_end; ++i)   /* i = 2 .. n_inner-2 */
        {
          /* 1) Compute B[i][*] from A. */
          {
            DATA_TYPE *Bi      = &B[i][j_start];
            DATA_TYPE *Ai_left = &A[i][j_start-1];
            DATA_TYPE *Ai      = &A[i][j_start];
            DATA_TYPE *Ai_right= &A[i][j_start+1];
            DATA_TYPE *Ai_up   = &A[i-1][j_start];
            DATA_TYPE *Ai_down = &A[i+1][j_start];

            for (j = j_start; j < j_end; ++j)
              {
                Bi[0] = c * (Ai[0] + Ai_left[0] + Ai_right[0] +
                             Ai_up[0] + Ai_down[0]);

                ++Bi;
                ++Ai_left;
                ++Ai;
                ++Ai_right;
                ++Ai_up;
                ++Ai_down;
              }
          }

          /* 2) Compute A[i-1][*] from B.
             At this point, rows B[i-2], B[i-1], and B[i] have all
             been computed from A at the current time step, so the
             stencil for A[i-1][*] is fully available. */
          {
            const int rowA = i - 1;

            DATA_TYPE *Ai      = &A[rowA][j_start];
            DATA_TYPE *Bi_left = &B[rowA][j_start-1];
            DATA_TYPE *Bi      = &B[rowA][j_start];
            DATA_TYPE *Bi_right= &B[rowA][j_start+1];
            DATA_TYPE *Bi_up   = &B[rowA-1][j_start];
            DATA_TYPE *Bi_down = &B[rowA+1][j_start];

            for (j = j_start; j < j_end; ++j)
              {
                /* A[rowA][j] = 0.2 * (B[rowA][j] + B[rowA][j-1] +
                                      B[rowA][j+1] + B[rowA+1][j] +
                                      B[rowA-1][j]); */
                Ai[0] = c * (Bi[0] + Bi_left[0] + Bi_right[0] +
                             Bi_up[0] + Bi_down[0]);

                ++Ai;
                ++Bi_left;
                ++Bi;
                ++Bi_right;
                ++Bi_up;
                ++Bi_down;
              }
          }
        }

      /* ---------- Final A row: i = n_inner - 2 ------------------------
         After the main loop, A[1..n_inner-3][*] have been computed.
         We still need the last interior row, A[n_inner-2][*].
         All its B-neighbors (rows n_inner-3, n_inner-2, n_inner-1)
         are available at this point. */
      {
        const int rowA = i_end - 1;  /* == n_inner - 2 */

        DATA_TYPE *Ai      = &A[rowA][j_start];
        DATA_TYPE *Bi_left = &B[rowA][j_start-1];
        DATA_TYPE *Bi      = &B[rowA][j_start];
        DATA_TYPE *Bi_right= &B[rowA][j_start+1];
        DATA_TYPE *Bi_up   = &B[rowA-1][j_start];
        DATA_TYPE *Bi_down = &B[rowA+1][j_start];

        for (j = j_start; j < j_end; ++j)
          {
            Ai[0] = c * (Bi[0] + Bi_left[0] + Bi_right[0] +
                         Bi_up[0] + Bi_down[0]);

            ++Ai;
            ++Bi_left;
            ++Bi;
            ++Bi_right;
            ++Bi_up;
            ++Bi_down;
          }
      }
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_jacobi_2d(tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
