/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations applied:
 *  - Introduce restrict-qualified row-pointer aliases for A and B to
 *    aid alias analysis and vectorization.
 *  - Hoist the constant stencil coefficient out of the loops.
 *  - Use row pointers inside the loops to reduce address arithmetic
 *    and improve cache locality.
 *  - Use a GCC vectorization hint (#pragma GCC ivdep) on the innermost
 *    loops; this is safe because A and B are distinct, non-overlapping
 *    allocations and individual rows do not overlap.
 *
 * The iteration space and update order are unchanged, preserving the
 * original Jacobi scheme semantics exactly.
 */
static
void kernel_jacobi_2d [[gnu::flatten, gnu::noinline]] (int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int t, i, j;

  /* Create restrict-qualified aliases to help the compiler assume
     that A and B do not alias and that different rows are independent. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE (*restrict B_)[n] = B;

  /* Hoist the stencil weight constant out of the loops. */
  const DATA_TYPE c0 = SCALAR_VAL(0.2);

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
    {
      /* First phase: B = stencil(A) */
      for (i = 1; i < _PB_N - 1; i++)
        {
          /* Row pointers for better locality and fewer address calculations. */
          DATA_TYPE *restrict Ai  = A_[i];
          DATA_TYPE *restrict Aim = A_[i-1];
          DATA_TYPE *restrict Aip = A_[i+1];
          DATA_TYPE *restrict Bi  = B_[i];

          /* Tell GCC it may safely vectorize this loop; all memory
             dependencies are handled by the algorithm structure and
             restrict-qualification. */
#pragma GCC ivdep
          for (j = 1; j < _PB_N - 1; j++)
            {
              Bi[j] = c0 * (Ai[j]     /* center  */
                           + Ai[j-1]  /* left    */
                           + Ai[j+1]  /* right   */
                           + Aip[j]   /* down    */
                           + Aim[j]); /* up      */
            }
        }

      /* Second phase: A = stencil(B) */
      for (i = 1; i < _PB_N - 1; i++)
        {
          DATA_TYPE *restrict Bi  = B_[i];
          DATA_TYPE *restrict Bim = B_[i-1];
          DATA_TYPE *restrict Bip = B_[i+1];
          DATA_TYPE *restrict Ai  = A_[i];

#pragma GCC ivdep
          for (j = 1; j < _PB_N - 1; j++)
            {
              Ai[j] = c0 * (Bi[j]     /* center  */
                           + Bi[j-1]  /* left    */
                           + Bi[j+1]  /* right   */
                           + Bip[j]   /* down    */
                           + Bim[j]); /* up      */
            }
        }
    }
#pragma endscop

}


