/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_jacobi_2d [[gnu::flatten, gnu::noinline]] (int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int t;

  /* Constant used in the stencil; hoisted out of the loops so it is
     computed only once instead of at every iteration. */
  const DATA_TYPE c0 = SCALAR_VAL(0.2);

  /* We use a flattened, restrict-qualified view of the 2D arrays.
     This has two purposes:
       - avoid repeated 2D index arithmetic inside the innermost loop;
       - give the compiler stronger aliasing information (via `restrict`)
         to enable more aggressive vectorization and reordering.
     The PolyBench framework allocates A and B as disjoint contiguous
     2D row-major arrays, so this is semantically correct. */
  DATA_TYPE *restrict Aflat = &A[0][0];
  DATA_TYPE *restrict Bflat = &B[0][0];

  /* Row stride in elements.  This is the actual leading dimension
     of the storage (n x n), as passed from main. */
  const int stride = n;

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
    {
      int i, j;

      /* First sweep: compute B from A.
         Loop bounds are kept identical to the original version
         (1 .. _PB_N-2) to preserve semantics exactly. */
      for (i = 1; i < _PB_N - 1; i++)
	{
	  /* Pointers to the three rows involved in the 5-point stencil:
	     row i-1, i, and i+1.  We start at column 1, since the
	     boundary columns (0 and n-1) are not updated. */
	  DATA_TYPE *a_im1 = Aflat + (size_t)(i - 1) * stride + 1;
	  DATA_TYPE *a_i   = Aflat + (size_t)i       * stride + 1;
	  DATA_TYPE *a_ip1 = Aflat + (size_t)(i + 1) * stride + 1;
	  DATA_TYPE *b_i   = Bflat + (size_t)i       * stride + 1;

	  /* Inner loop streams through the row with simple pointer
	     increments. Every iteration advances the four pointers by
	     one element.  This minimizes address calculations and
	     exposes a straightforward pattern for the vectorizer. */
#pragma GCC ivdep
	  for (j = 1; j < _PB_N - 1; j++)
	    {
	      /* B[i][j] = 0.2 * (A[i][j] +
	                          A[i][j-1] + A[i][j+1] +
	                          A[i-1][j] + A[i+1][j]); */
	      *b_i = c0 * (*a_i + a_i[-1] + a_i[1] + *a_ip1 + *a_im1);

	      /* Move to the next column. */
	      ++a_im1;
	      ++a_i;
	      ++a_ip1;
	      ++b_i;
	    }
	}

      /* Second sweep: compute A from B, with the same pattern but
         swapping the roles of A and B. */
      for (i = 1; i < _PB_N - 1; i++)
	{
	  DATA_TYPE *b_im1 = Bflat + (size_t)(i - 1) * stride + 1;
	  DATA_TYPE *b_i   = Bflat + (size_t)i       * stride + 1;
	  DATA_TYPE *b_ip1 = Bflat + (size_t)(i + 1) * stride + 1;
	  DATA_TYPE *a_i   = Aflat + (size_t)i       * stride + 1;

#pragma GCC ivdep
	  for (j = 1; j < _PB_N - 1; j++)
	    {
	      /* A[i][j] = 0.2 * (B[i][j] +
	                          B[i][j-1] + B[i][j+1] +
	                          B[i-1][j] + B[i+1][j]); */
	      *a_i = c0 * (*b_i + b_i[-1] + b_i[1] + *b_ip1 + *b_im1);

	      ++b_im1;
	      ++b_i;
	      ++b_ip1;
	      ++a_i;
	    }
	}
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_jacobi_2d(tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
