  const int nPB  = _PB_N;
  const int tPB  = _PB_TSTEPS;

  /* Hoist the scalar coefficient out of the loops to avoid
     recomputing it. */
  const DATA_TYPE c = SCALAR_VAL(0.2);

  /* Note: 'tsteps' and 'n' are still used indirectly via _PB_TSTEPS
     and _PB_N, so no need to silence unused-parameter warnings. */

#pragma scop
  /* Parallelize across the spatial dimension. A single parallel region
     is used for all time steps to amortize thread creation cost.
     Without -fopenmp these pragmas are ignored and the code remains
     sequential. */
#pragma omp parallel default(none) shared(A,B,nPB,tPB,c)
  {
    for (int t = 0; t < tPB; ++t)
    {
      /* First Jacobi sweep: compute B from A.
         We use row pointers (a_im1, a_i, a_ip1, b_i) to:
           - improve data locality in the inner loop
           - reduce address computation overhead
         The 'restrict' here expresses that these row slices do not
         overlap with each other, which holds for regular 2D arrays and
         the way PolyBench allocates A and B. */

#pragma omp for schedule(static)
      for (int i = 1; i < nPB - 1; ++i)
      {
        DATA_TYPE * restrict a_im1 = A[i-1];
        DATA_TYPE * restrict a_i   = A[i];
        DATA_TYPE * restrict a_ip1 = A[i+1];
        DATA_TYPE * restrict b_i   = B[i];

        /* Inner loop is perfectly vectorizable: no loop-carried
           dependencies and only forward stores into B.  The ivdep
           pragma tells GCC that there are no hidden dependencies that
           would prevent vectorization, even in the presence of pointer
           aliasing between A and B (which does not occur here). */
#pragma GCC ivdep
        for (int j = 1; j < nPB - 1; ++j)
        {
          b_i[j] = c * ( a_i[j]
                       + a_i[j-1]
                       + a_i[j+1]
                       + a_ip1[j]
                       + a_im1[j] );
        }
      }

      /* Second Jacobi sweep: compute A from B, symmetrically to the
         first sweep.  Again use row pointers for better locality and
         cheaper addressing. */

#pragma omp for schedule(static)
      for (int i = 1; i < nPB - 1; ++i)
      {
        DATA_TYPE * restrict b_im1 = B[i-1];
        DATA_TYPE * restrict b_i   = B[i];
        DATA_TYPE * restrict b_ip1 = B[i+1];
        DATA_TYPE * restrict a_i   = A[i];

#pragma GCC ivdep
        for (int j = 1; j < nPB - 1; ++j)
        {
          a_i[j] = c * ( b_i[j]
                       + b_i[j-1]
                       + b_i[j+1]
                       + b_ip1[j]
                       + b_im1[j] );
        }
      }
      /* Implicit barrier at the end of each omp for ensures that the
         B-sweep is fully completed before the A-sweep, and that the
         A-sweep is fully completed before the next time step. */
    }
  }
#pragma endscop

}


