  DATA_TYPE (*restrict B_)[n] = B;

  /* Hoist constant multiplier. */
  const DATA_TYPE c = SCALAR_VAL(0.2);

  int t, i, j;

#pragma scop
  for (t = 0; t < tsteps_; t++)
    {
