         Each (i,j) update depends only on A (previous time step),
         so the loop nest is fully parallelizable and vectorizable. */

#ifdef _OPENMP
# pragma omp parallel for private(j) schedule(static) if (n_pb >= 32)
#endif
      for (i = 1; i < n_pb - 1; i++)
